const express = require('express');
const app = express();
app.use(express.json());

// 用户偏好默认配置
const defaultPrefs = { theme: 'light', language: 'zh-CN', notifications: { email: true } };

// 递归合并偏好：for-in 键遍历 + 递归赋值，未过滤危险键名
function mergePrefs(target, source) {
  for (const key in source) {
    if (typeof source[key] === 'object' && source[key] !== null) {
      if (!target[key]) target[key] = {};
      mergePrefs(target[key], source[key]);   // 递归深入子对象
    } else {
      target[key] = source[key];              // 键名未校验，直接写入
    }
  }
  return target;
}

// POST /prefs/update 保存用户偏好
// 载荷：{"__proto__": {"isAdmin": true}} —— __proto__ 键把递归目标引向 Object.prototype
app.post('/prefs/update', (req, res) => {
  mergePrefs(defaultPrefs, req.body);         // 外部 JSON 载荷直接进入递归合并
  res.json({ ok: true, prefs: defaultPrefs });
});

// GET /admin 权限判定：普通对象沿原型链读取 isAdmin
app.get('/admin', (req, res) => {
  const user = { name: 'guest' };             // 自身不存在 isAdmin 属性
  if (user.isAdmin) {                         // 命中被污染的 Object.prototype.isAdmin
    res.send('已授权进入管理面板');
  } else {
    res.status(403).send('禁止访问');
  }
});

app.listen(3000);
```

